using UnityEngine;
using GoogleMobileAds.Api;
using UnityEngine.UI;
using TMPro; // להוספת Text

/**
 * Display Google AdMob dummy ads, for testing the ad integration mechanism.
 * Most code was generated by Claude.ai.
 */


public class TestAds : MonoBehaviour {
    private InterstitialAd interstitialAd;
    private BannerView bannerView;

    [SerializeField] TextMeshProUGUI statusText;  // הצגת הסטטוס בטקסט לצורך מעקב וניפוי שגיאות

    [SerializeField] bool showRealAds;

    // Test Ad Unit IDs - עובדים בלי רישום!
    string testInterstitialId = "ca-app-pub-3940256099942544/1033173712";
    string testBannerId = "ca-app-pub-3940256099942544/6300978111";

    string realInterstitialId = "ca-app-pub-4131841895603404/2839088118";
    string realBannerId = "ca-app-pub-4131841895603404/3697724270";

    string InterstitialId() {
        return showRealAds ? realInterstitialId : testInterstitialId;
    }

    string BannerId() {
        return showRealAds ? realBannerId : testBannerId;
    }




    void Start() {
        UpdateStatus("Starting AdMob...");
        MobileAds.Initialize(initStatus => {
            UpdateStatus("AdMob initialized!");
            Debug.Log("✅ AdMob initialized!");
            LoadBanner();
            LoadInterstitial();
        });
    }

    // טען פרסומת כרזה
    void LoadBanner() {
        UpdateStatus("Loading banner...");
        Debug.Log("Loading banner...");

        // מחק banner ישן אם יש
        if (bannerView != null) {
            bannerView.Destroy();
        }

        bannerView = new BannerView(BannerId(), AdSize.SmartBanner, AdPosition.Bottom);

        // הוסף event listeners
        bannerView.OnBannerAdLoaded += () => {
            UpdateStatus("Banner loaded!");
            Debug.Log("✅ Banner loaded and displayed!");
        };

        bannerView.OnBannerAdLoadFailed += (LoadAdError error) => {
            UpdateStatus("Banner failed: " + error.GetMessage());
            Debug.LogError("❌ Banner failed: " + error.GetMessage());
        };

        AdRequest request = new AdRequest();
        bannerView.LoadAd(request);
    }

    // טען פרסומת מסך מלא
    void LoadInterstitial() {
        UpdateStatus("Loading interstitial...");
        Debug.Log("Loading interstitial...");

        AdRequest request = new AdRequest();

        InterstitialAd.Load(InterstitialId(), request,
            (InterstitialAd ad, LoadAdError error) => {
                if (error != null) {
                    UpdateStatus("Interstitial failed: " + error.GetMessage());
                    Debug.LogError("❌ Interstitial failed: " + error.GetMessage());
                    interstitialAd = null;

                    // נסה שוב אחרי 5 שניות
                    Invoke(nameof(LoadInterstitial), 5f);
                    return;
                }

                interstitialAd = ad;
                UpdateStatus("Interstitial ready!");
                Debug.Log("✅ Interstitial loaded!");

                // רישום לאירועים
                interstitialAd.OnAdFullScreenContentClosed += () => {
                    Debug.Log("Interstitial closed");
                    LoadInterstitial(); // טען פרסומת חדשה
                };
            });
    }

    // הצג פרסומת מסך מלא
    public void ShowInterstitial() {
        Debug.Log("ShowInterstitial called");
        if (interstitialAd != null && interstitialAd.CanShowAd()) {
            UpdateStatus("Showing ad...");
            Debug.Log("✅ Showing interstitial ad");
            interstitialAd.Show();
        } else {
            UpdateStatus("Ad not ready yet");
            Debug.LogWarning("⚠️ Interstitial not ready. Loading...");
            LoadInterstitial();
        }
    }


    void UpdateStatus(string message) {
        if (statusText != null) {
            statusText.text = message;
        }
    }
}
